/**
 * charset.mjs
 *
 * The Bech32 base-32 character set (BIP-173) and the lookup helpers used by
 * the encoder/decoder.  The ordering of the alphabet is significant: the index
 * of a character inside CHARSET *is* its 5-bit value.
 */

/** The 32 data characters, in canonical BIP-173 order. */
export const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';

/** The separator between the human-readable part and the data part. */
export const SEPARATOR = '1';

/**
 * Reverse lookup table: character -> 5-bit value.
 * Built once at module load so decoding stays O(1) per character.
 */
const CHARSET_REV = new Map();
for (let i = 0; i < CHARSET.length; i += 1) {
  CHARSET_REV.set(CHARSET[i], i);
}

/**
 * Mirrors Python's `CHARSET.find(ch)`: the 5-bit value of `ch`, or -1 when the
 * character is not part of the Bech32 alphabet.
 *
 * @param {string} ch single character
 * @returns {number} value in [0, 31], or -1
 */
export function charsetFind(ch) {
  const value = CHARSET_REV.get(ch);
  return value === undefined ? -1 : value;
}

/**
 * Whether every character of `str` belongs to the Bech32 alphabet.
 * Mirrors `all(x in CHARSET for x in str)`.
 *
 * @param {string} str
 * @returns {boolean}
 */
export function isCharsetOnly(str) {
  for (const ch of str) {
    if (!CHARSET_REV.has(ch)) return false;
  }
  return true;
}

