/**
 * polymod.mjs
 *
 * The BCH code primitives behind the Bech32 checksum: the `polymod` generator
 * step and the human-readable-part expansion that seeds it.
 *
 * All arithmetic stays inside 30 bits, so plain JavaScript numbers with
 * bitwise operators are exact — no big integers needed.
 */

/** Generator coefficients of the BCH code used by Bech32 (BIP-173). */
const GENERATOR = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

/**
 * Internal checksum function over a list of 5-bit values.
 *
 * @param {number[]} values 5-bit values
 * @returns {number} the polymod residue
 */
export function bech32Polymod(values) {
  let chk = 1;
  for (const value of values) {
    const top = chk >>> 25;
    // Keep the low 25 bits, shift in the next 5-bit symbol.
    chk = ((chk & 0x1ffffff) << 5) ^ value;
    for (let i = 0; i < 5; i += 1) {
      if ((top >>> i) & 1) {
        chk ^= GENERATOR[i];
      }
    }
    // Coerce back to an unsigned 30-bit-safe value.
    chk >>>= 0;
  }
  return chk >>> 0;
}

/**
 * Expand the human-readable part into values for checksum computation:
 * the high bits of every character, a zero separator, then the low bits.
 *
 * @param {string} hrp human-readable part (already lower-cased)
 * @returns {number[]} expanded 5-bit values
 */
export function bech32HrpExpand(hrp) {
  const high = [];
  const low = [];
  for (const ch of hrp) {
    const code = ch.codePointAt(0);
    high.push(code >> 5);
    low.push(code & 31);
  }
  return high.concat([0], low);
}

