import { bech32HrpExpand, bech32Polymod } from './polymod.mjs';

/**
 * Verify a checksum given the human-readable part and the full data part
 * (payload **including** the trailing 6 checksum symbols).
 *
 * @param {string} hrp
 * @param {number[]} data 5-bit values, checksum included
 * @returns {boolean}
 */
export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod(bech32HrpExpand(hrp).concat(data)) === 1;
