/**
 * bech32.mjs
 *
 * Public Bech32 surface, behaviourally equivalent to the `bech32` Python
 * package: `bech32_decode` returns a `[hrp, data]` pair and degrades to
 * `[null, null]` (Python's `(None, None)`) for *any* malformed input rather
 * than raising.
 */

import { CHARSET, SEPARATOR, charsetFind, isCharsetOnly } from './charset.mjs';
import { bech32CreateChecksum, bech32VerifyChecksum } from './checksum.mjs';

/** Maximum total length of a Bech32 string, per BIP-173. */
const MAX_LENGTH = 90;

/** Number of trailing data symbols that form the checksum. */
const CHECKSUM_LENGTH = 6;

/**
 * Python's `str.lower()` / `str.upper()` mixed-case guard plus the printable
 * US-ASCII range check: every character must satisfy 33 <= ord(c) <= 126, and
 * the string may not mix cases.
 *
 * Iteration is by code point (like Python), so astral characters count once.
 *
 * @param {string} bech
 * @returns {boolean} true when the string is structurally acceptable
 */
function hasValidCharacters(bech) {
  for (const ch of bech) {
    const code = ch.codePointAt(0);
    if (code < 33 || code > 126) return false;
  }
  // Only reachable for pure printable ASCII, where JS and Python case mapping
  // agree, so this matches `bech.lower() != bech and bech.upper() != bech`.
  return bech.toLowerCase() === bech || bech.toUpperCase() === bech;
}

/**
 * Validate a Bech32 string and determine its hrp and data part.
 *
 * @param {string} bech the candidate Bech32 string
 * @returns {[string, number[]] | [null, null]} `[hrp, data]` or `[null, null]`
 */
export function bech32Decode(bech) {
  if (typeof bech !== 'string' || !hasValidCharacters(bech)) {
    return [null, null];
  }

  const lowered = bech.toLowerCase();
  const pos = lowered.lastIndexOf(SEPARATOR);

  // Need a non-empty hrp, room for the checksum, and a bounded total length.
  if (pos < 1 || pos + 1 + CHECKSUM_LENGTH > lowered.length || lowered.length > MAX_LENGTH) {
    return [null, null];
  }

  const dataPart = lowered.slice(pos + 1);
  if (!isCharsetOnly(dataPart)) {
    return [null, null];
  }

  const hrp = lowered.slice(0, pos);
  const data = [];
  for (const ch of dataPart) {
    data.push(charsetFind(ch));
  }

  if (!bech32VerifyChecksum(hrp, data)) {
    return [null, null];
  }

  return [hrp, data.slice(0, data.length - CHECKSUM_LENGTH)];
}

/**
 * Compute a Bech32 string given an hrp and a sequence of 5-bit data values.
 *
 * @param {string} hrp
 * @param {number[]} data 5-bit payload values
 * @returns {string}
 */
export function bech32Encode(hrp, data) {
  const combined = data.concat(bech32CreateChecksum(hrp, data));
  let out = `${hrp}${SEPARATOR}`;
  for (const value of combined) {
    out += CHARSET[value];
  }
  return out;
}

