/**
 * pyrepr.mjs
 *
 * Renders JavaScript values exactly the way CPython's `repr()` would, so that
 * `print(result)` of a `(hrp, data)` tuple can be reproduced byte for byte.
 */

/** Characters that CPython escapes with a short backslash sequence. */
const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

/**
 * Python's `repr()` for a string.
 *
 * CPython prefers single quotes, but switches to double quotes when the value
 * contains a single quote and no double quote, so the quote never needs
 * escaping.  Control characters become `\xNN` escapes.
 *
 * @param {string} value
 * @returns {string}
 */
export function pyReprStr(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";

  let body = '';
  for (const ch of value) {
    const short = SHORT_ESCAPES.get(ch);
    if (short !== undefined) {
      body += short;
      continue;
    }
    if (ch === quote) {
      body += `\\${ch}`;
      continue;
    }
    const code = ch.codePointAt(0);
    if (code < 0x20 || code === 0x7f) {
      body += `\\x${code.toString(16).padStart(2, '0')}`;
      continue;
    }
    body += ch;
  }

  return `${quote}${body}${quote}`;
}

/**
 * Python's `repr()` for an int.
 *
 * @param {number} value
 * @returns {string}
 */
export function pyReprInt(value) {
  return String(value);
}

/**
 * Python's `repr()` for a list: `[]`, `[1]`, `[1, 2]`.
 *
 * @param {unknown[]} values
 * @returns {string}
 */
export function pyReprList(values) {
  return `[${values.map(pyRepr).join(', ')}]`;
}

/**
 * Python's `repr()` for a tuple.  Note the trailing comma for 1-tuples.
 *
 * @param {unknown[]} values
 * @returns {string}
 */
export function pyReprTuple(values) {
  if (values.length === 1) return `(${pyRepr(values[0])},)`;
  return `(${values.map(pyRepr).join(', ')})`;
}

/**
 * Generic dispatcher: `repr()` for the value kinds this program produces.
 *
 * @param {unknown} value
 * @returns {string}
 */
export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'string') return pyReprStr(value);
  if (typeof value === 'number') return pyReprInt(value);
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (Array.isArray(value)) return pyReprList(value);
  return String(value);
}

