/**
 * argparse.mjs
 *
 * A minimal, dependency-free re-implementation of the slice of CPython's
 * `argparse` that this program exercises: long/short options, `--opt=value`,
 * unique-prefix abbreviations, the negative-number heuristic, `--`, and the
 * exact `usage:` / `error:` / `--help` wording and exit codes.
 */

import { basename } from 'node:path';

/** CPython's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** Exit status argparse uses for command-line errors. */
const ERROR_EXIT_CODE = 2;

/**
 * The program name argparse derives from `sys.argv[0]`.
 *
 * @returns {string}
 */
export function progName() {
  return basename(process.argv[1] ?? 'test2.mjs');
}

/**
 * Parser for the fixed option set `[-h] --a A`.
 */
export class ArgumentParser {
  /**
   * @param {string} [prog] program name shown in usage/error output
   */
  constructor(prog = progName()) {
    this.prog = prog;
    /** @type {Map<string, {dest: string, nargs: number, metavar: string}>} */
    this.options = new Map();
    /** @type {string[]} */
    this.required = [];
  }

  /**
   * Register an option, argparse's `add_argument` for the cases we need.
   *
   * @param {string[]} flags e.g. `['-h', '--help']`
   * @param {{dest: string, nargs?: number, required?: boolean, metavar?: string}} spec
   */
  addArgument(flags, spec) {
    const action = {
      dest: spec.dest,
      nargs: spec.nargs === undefined ? 1 : spec.nargs,
      metavar: spec.metavar ?? spec.dest.toUpperCase(),
      flags,
    };
    for (const flag of flags) {
      this.options.set(flag, action);
    }
    if (spec.required) this.required.push(flags[flags.length - 1]);
  }

  /** @returns {string} the single-line `usage:` string. */
  formatUsage() {
    return `usage: ${this.prog} [-h] --a A\n`;
  }

  /** @returns {string} the full `--help` text. */
  formatHelp() {
    return (
      `${this.formatUsage()}\n` +
      'options:\n' +
      '  -h, --help  show this help message and exit\n' +
      '  --a A\n'
    );
  }

  /** Print help to stdout and exit 0, like argparse's help action. */
  printHelpAndExit() {
    process.stdout.write(this.formatHelp());
    process.exit(0);
  }

  /**
   * Print `usage` + `prog: error: message` to stderr and exit 2.
   *
   * @param {string} message
   * @returns {never}
   */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(ERROR_EXIT_CODE);
  }

  /**
   * CPython's `_parse_optional`: classify a token.
   *
   * @param {string} token
   * @returns {null | {action: object|null, optionString: string, explicitArg: string|null}}
   *   `null` means "this is a positional"; an entry with `action: null` means
   *   "looks like an option but is unknown".
   */
  parseOptional(token) {
    if (token === '') return null;
    if (token[0] !== '-') return null;

    const exact = this.options.get(token);
    if (exact !== undefined) {
      return { action: exact, optionString: token, explicitArg: null };
    }

    // A lone '-' was meant to be a positional.
    if (token.length === 1) return null;

    if (token.includes('=')) {
      const eq = token.indexOf('=');
      const name = token.slice(0, eq);
      const explicitArg = token.slice(eq + 1);
      const action = this.options.get(name);
      if (action !== undefined) {
        return { action, optionString: name, explicitArg };
      }
    }

    const candidates = this.getOptionTuples(token);
    if (candidates.length > 1) {
      const names = candidates.map((c) => c.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${names}`);
    }
    if (candidates.length === 1) return candidates[0];

    // No option strings look like negative numbers, so these are positionals.
    if (NEGATIVE_NUMBER.test(token)) return null;
    if (token.includes(' ')) return null;

    return { action: null, optionString: token, explicitArg: null };
  }

  /**
